cat > /tmp/test-thresholds.js << 'EOF'
const { generateReport, runEvaluations } = await import('./packages/frai-core/src/eval/index.js');

// Test 1: All thresholds pass
console.log('Test 1: All thresholds pass');
const evaluations = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'world']
});
const report = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.5,
    toxicity: 0.8
  }
});
console.log('passed:', report.passed);
console.log('thresholds:', report.thresholds);
console.log('');

// Test 2: One threshold fails
console.log('Test 2: One threshold fails');
const evaluations2 = runEvaluations({
  outputs: ['Hello'],
  references: ['goodbye']
});
const report2 = generateReport({
  evaluations: evaluations2,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.9
  }
});
console.log('passed:', report2.passed);
console.log('thresholds:', report2.thresholds);
console.log('');

// Test 3: No thresholds
console.log('Test 3: No thresholds (backward compatibility)');
const report3 = generateReport({
  evaluations: evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});
console.log('passed:', report3.passed);
console.log('thresholds:', report3.thresholds);
EOF
node /tmp/test-thresholds.js
